begin;
select plan(30);
insert into auth.users(id,aud,role,is_anonymous,raw_user_meta_data)
select ('60000000-0000-4000-8000-00000000000'||n)::uuid,'authenticated','authenticated',true,'{}' from generate_series(1,3)n;
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select public.create_code_band('Original band','Original owner','드럼','original-pass','123456','654321');
select set_config('test.original',(public.current_band_identity()->>'band_id'),true);
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000002","is_anonymous":true}',true);
select is(public.current_band_identity(),null::jsonb,'unmapped anonymous device has no identity/context');
select is(public.create_test_band('Me','123','123456')->>'error','INVALID_INPUT','invalid fixture credentials rejected before seeding');
select ok((public.create_test_band('내 테스트','test1234','112233')->>'ok')::boolean,'creates independent test band and logs caller in as its owner');
select set_config('test.band',public.current_band_identity()->>'band_id',true);
select is(public.current_band_identity()->>'nickname','내 테스트','caller nickname is used');
select is(public.current_band_identity()->'member'->>'role','leader','caller is the test leader');
select is(public.current_band_identity()->>'context_version','1','identity contains a versioned context');
select is(public.current_band_identity()->'band'->>'id',current_setting('test.band'),'band snapshot matches caller band');
select is(public.current_band_identity()->'member'->>'band_id',current_setting('test.band'),'member snapshot matches band');
select is((select count(*)::int from public.band_members where band_id=current_setting('test.band')::uuid),1,'fixture has one real member without fake Auth rows');
select is((select count(*)::int from public.songs where band_id=current_setting('test.band')::uuid),4,'four named song scenarios created');
select is((select count(*)::int from public.unavailable_dates where band_id=current_setting('test.band')::uuid),2,'two future unavailable dates seeded');
select set_config('test.round',(select id::text from public.planning_rounds where band_id=current_setting('test.band')::uuid),true);
select is((select status from public.round_submissions where round_id=current_setting('test.round')::uuid),'submitted','leader dates already submitted');
select is((select end_date-start_date+1 from public.planning_rounds where id=current_setting('test.round')::uuid),60,'test round spans normal 60 days');
select is((select count(*)::int from public.song_votes where round_id=current_setting('test.round')::uuid),3,'A C D votes present and B remains pending');
select is((select count(*)::int from public.song_difficulties d join public.songs s on s.id=d.song_id where s.band_id=current_setting('test.band')::uuid and d.part_key='기타'),3,'difficulty uses the actual Korean participant part key');
select set_config('test.a',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 A]%'),true);
select set_config('test.d',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 D]%'),true);
select lives_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date,array[current_setting('test.a')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'A is actually eligible for leader finalization');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(now() at time zone 'Asia/Seoul')::date,array[current_setting('test.d')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','SONG_NOT_ELIGIBLE','D is ineligible until difficulty registration');
select is((select count(*)::int from public.confirmed_plans where band_id=current_setting('test.band')::uuid),1,'failed D finalization preserves confirmed A');
select is(public.create_test_band('Duplicate','test5678','112233')->>'error','ALREADY_SIGNED_IN','cannot create second fixture over current member');
select is((select count(*)::int from public.songs where band_id=current_setting('test.band')::uuid),4,'retry does not duplicate fixture data');
select is((select count(*)::int from public.bands where id=current_setting('test.original')::uuid),0,'test leader cannot read original band');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select is(public.create_test_band('Overwrite','test5678','112233')->>'error','ALREADY_SIGNED_IN','original owner cannot replace existing band with fixture');
select is(public.current_band_identity()->>'band_id',current_setting('test.original'),'original membership preserved');
select is(public.current_band_identity()->>'nickname','Original owner','original profile preserved');
reset role;
-- Force a late seeding error to verify rollback of the entire newly-created band.
create function private.fail_fixture_insert() returns trigger language plpgsql set search_path='' as $$
begin
 if new.created_by='60000000-0000-4000-8000-000000000003' then raise exception 'TEST_FIXTURE_FAILURE'; end if;
 return new;
end $$;
create trigger test_fixture_failure before insert on public.songs for each row execute function private.fail_fixture_insert();
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000003","is_anonymous":true}',true);
select throws_ok($$select public.create_test_band('Rollback','test1234','112233')$$,'P0001','TEST_FIXTURE_FAILURE','late fixture failure propagates instead of partial success');
reset role;
select is((select count(*)::int from public.band_members where user_id='60000000-0000-4000-8000-000000000003'),0,'failed fixture leaves no membership');
select is((select count(*)::int from private.member_pins where user_id='60000000-0000-4000-8000-000000000003'),0,'failed fixture leaves no PIN');
select is((select count(*)::int from public.bands where leader_user_id='60000000-0000-4000-8000-000000000003'),0,'failed fixture leaves no band');
select is((select count(*)::int from auth.users where id::text like '60000000-%'),3,'seeding never creates synthetic Auth accounts');
select ok(not has_function_privilege('anon','public.create_test_band(text,text,text)','EXECUTE'),'unauthenticated fixture creation denied');
select * from finish();
rollback;
